async function loadIndependentPose(path) {
  const response=await fetch(new URL(path,import.meta.url));
  if(!response.ok)throw new Error('Unable to load camera data: '+path);
  const data=await response.json();
  return {fps:Number(data.fps??24),poses:data.cameras_interp.map(matrix=>matrix.flat())};
}
